function setLink(node, targetId, animation='SMART_ANIMATE', trigger='ON_CLICK'){
  node.reactions = [{
    trigger: {type: trigger},
    actions: [{
      type: 'NODE',
      destinationId: targetId,
      navigation: 'NAVIGATE',
      transition: {type: animation==='SMART_ANIMATE'?'SMART_ANIMATE':'DISSOLVE', easing:{type:'EASE_OUT'}, duration:0.3},
      preserveScrollPosition:false
    }]
  }];
}
function setOverlay(node, targetId){
  node.reactions = [{
    trigger: {type:'ON_CLICK'},
    actions: [{
      type:'NODE',
      destinationId: targetId,
      navigation:'OVERLAY',
      transition:{type:'SMART_ANIMATE', easing:{type:'EASE_OUT'}, duration:0.3},
      preserveScrollPosition:false,
      overlayRelativePosition:{x:0,y:0}
    }]
  }];
}

